 $hc=User::create(['name'=>'Nadia Putri','email'=>'hc@growpath.test','password'=>Hash::make('password'),'role'=>'hc']); $user=User::create(['name'=>'Aliyah Rahma','email'=>'aliyah@growpath.test','password'=>Hash::make('password'),'role'=>'employee']);
