 $assessment=$employee->assessments()->create(['assessment_date'=>'2026-08-20','status'=>'submitted']); $levels=['Leadership'=>2,'Communication'=>4,'Problem Solving'=>2,'Analytical Thinking'=>3,'Collaboration'=>4]; foreach($competencies as $c){$current=$levels[$c->name];$required=$senior->competencies()->whereKey($c->id)->first()->pivot->required_level;$gap=max(0,$required-$current);$assessment->details()->create(['competency_id'=>$c->id,'level'=>$current]);GapAnalysis::create(['employee_id'=>$employee->id,'competency_id'=>$c->id,'current_level'=>$current,'required_level'=>$required,'gap'=>$gap,'priority'=>$gap>=2?'high':($gap?'medium':'none')]);}
 PerformanceReview::create(['employee_id'=>$employee->id,'reviewer_id'=>$hc->id,'period'=>'Jan — Jun 2026','overall_score'=>4.2,'target_achievement'=>4,'quality_of_work'=>4,'productivity'=>4,'collaboration'=>5,'strengths'=>'Communication, Collaboration','development_areas'=>'Leadership, Problem Solving','manager_feedback'=>'Aliyah menunjukkan kolaborasi yang sangat baik. Fokus pengembangan berikutnya adalah keberanian memimpin proyek lintas unit.','status'=>'published']);
